android.extraProguardRules:
# Keep rules so first-time minification can't strip native modules that are
# resolved by reflection/JNI at runtime. Additive keeps only — they can prevent
# a crash but never cause one.
-keepattributes *Annotation*,Signature,InnerClasses,EnclosingMethod
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; @com.facebook.jni.annotations.DoNotStrip *; }
-keep,includedescriptorclasses class * { native <methods>; }
# React Native / Hermes bridge
-keep class com.facebook.react.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.jni.** { *; }
-dontwarn com.facebook.react.**
# Reanimated / Worklets (JNI-heavy)
-keep class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.worklets.** { *; }
-keep class com.facebook.react.turbomodule.** { *; }
# Expo modules are discovered reflectively
-keep class expo.modules.** { *; }
-keep class expo.modules.securestore.** { *; }
-dontwarn expo.modules.**
# OkHttp (the network stack under axios' native layer)
-dontwarn okhttp3.**
-dontwarn okio.**
